};

/**
 * @method
 * @name tr_Save_OnSuccess
 * @description tr Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Save_OnSuccess = async function() {
    try {
        if (scwin.vJobType === "I") {
            await $c.win.alert("성공적으로 저장 되었습니다.");
        } else if (scwin.vJobType === "U") {
            await $c.win.alert("성공적으로 수정 되었습니다.");
        } else if (scwin.vJobType === "D") {
            scwin.indexingElasitcSearch();
            await $c.win.alert("성공적으로 삭제 되었습니다.");
            if (scwin.isFileDelete) {
                // 파일이 삭제되어 ElasticSearch 호출
                scwin.callElasticFileNoti();
            }
        }
        await scwin.searchRet();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07106.tr_Save_OnSuccess" });
    }
};

