/**
 * @method
 * @name save
 * @description save 처리
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(jobType) {
    let vScrenProcTpCd;
    scwin.vJobType = jobType;
    if (jobType === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType === "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    if (jobType === "D") {
        if ($c.cp.isModified(dts_Cmt) || $c.cp.isModified(dts_ReqInf)) {
            dts_ReqInf.setCellData(1, "LST_COMITE_RSLT_SAVE_EMP_NO", js_emp_no);
            tr_Save.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_tr_Save",
                action : "/prelistingKosdaq.do",
                ref : "dts_ReqInf,dts_Cmt,dts_fileList",
                target : "tr_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
    if (jobType === "I" || jobType === "U") {
        if (!$c.cp.isModified(dts_Retr) && !$c.cp.isModified(dts_ReqInf) && !$c.cp.isModified(dts_fileList)) {
            await $c.win.alert(scwin.MGS_NO_UPDT);
            return;
        }
        let rtn = confirm('저장 하시겠습니까?');
        if (rtn === 1) {
            if ($c.cp.isModified(dts_Retr) || $c.cp.isModified(dts_ReqInf)) {
                dts_ReqInf.setCellData(1, "LST_COMITE_RSLT_SAVE_EMP_NO", js_emp_no);
                tr_Save.KeyName = "toinb_dataid4";
                const sbmOptions = {
                    id : "sbm_tr_Save",
                    action : "/prelistingKosdaq.do",
                    ref : "dts_ReqInf,dts_Retr,dts_fileList",
                    target : "tr_Save=body.content",
                    isProcessMsg : false
                };

                const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
            } else if ($c.cp.isModified(dts_fileList)) {
                await scwin.fileSave();
            }
        }
    }
};

/**
 * @method
 * @name fileSave
 * @description file Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileSave = async function() {
    const sbmOptions = {
