/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    let rtn = confirm('삭제 하시겠습니까?');
    if (rtn === 1) {
        scwin.vReload = "Y";
        if (dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "ATTACH_FILE_NM2") !== "") {
            scwin.isFileDelete = true;
            scwin.eBzProcsNo = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO");
            scwin.eComideDd = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "COMITE_DD");
            scwin.eSeq = "2";
        }
        dts_Cmt.removeRow(dts_Cmt.getRowPosition());
        await scwin.save("D");
    }
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function() {
    if (dts_Cmt.getRowPosition() > 0) {
        scwin.fn_GetPar = scwin.getParUpdate;
        scwin.fn_SetPar = undefined;
        const options = {
            id: "ULDSTF07109",
            title: "위원회결과 수정",
            type: "browserPopup",
            width: "580px",
            height: "430px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstinvstg/ULDSTF07109.gfm", options);
    }
};

