/**
 * @method
 * @name checkComiteDd
 * @description check Comite Dd 처리
 * @param {String} comiteDd comiteDd
 * @returns {void}
 * @hidden N
 */
scwin.checkComiteDd = function(comiteDd) {
    if (dts_Cmt.getRowCount() > 0) {
        for (let i = 0; i < dts_Cmt.getRowCount(); i++) {
            if (comiteDd === dts_Cmt.getCellData(i, "COMITE_DD")) {
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name callElasticFileNoti
 * @description call Elastic File Noti 처리
 * @returns {void}
 * @hidden N
 */
scwin.callElasticFileNoti = function() {
    $.ajax({
        type: "POST",
        url: "/elasticNoti.do",
        data: {
            method: "notiElasticCommon",
            P_bzProcsNo: scwin.eBzProcsNo,
            P_comiteDd: scwin.eComideDd,
            P_seq: scwin.eSeq,
            url: "/index/tbld_comite_rslt_attach/kafka",
            type: "POST"
        },
        async: true
    });
    scwin.isFileDelete = false;
};

